"""Independent deterministic fixtures; prepare saves expectations before any checker execution."""
import sys
sys.dont_write_bytecode = True
import json, hashlib, copy, runpy, traceback
from pathlib import Path
ROOT = Path.cwd()
OUT = ROOT / '.session/artifacts'
DATA = ROOT / 'benchmark/attempt-evidence-0143.json'

def pack(x):
    return json.dumps(x, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()

def digest(b):
    return hashlib.sha256(b).hexdigest()

def strict(text):
    def pairs(rows):
        d = {}
        for k,v in rows:
            if k in d: raise ValueError('duplicate')
            d[k] = v
        return d
    def bad(x): raise ValueError('nonfinite')
    return json.loads(text, object_pairs_hook=pairs, parse_constant=bad)

def ent(a,k):
    return next((e for e in a['evidence'] if e['kind']==k),None)

def original(f,a,k):
    e=ent(a,k)
    if e is None or e['presence']=='absent': return None
    return bytes.fromhex(f['payloads'][e['payload_ref']]['hex'])

def put(f,a,k,b):
    e=ent(a,k); ref='synthetic:payload-review-'+str(a['attempt_order'])+'-'+k
    try: text=b.decode('utf-8')
    except UnicodeError: text=None
    f['payloads'][ref]={'encoding':'hex','hex':b.hex(),'byte_size':len(b),'sha256':digest(b),'utf8':text}
    e.update(presence='present',payload_ref=ref)

def state(f,a):
    e=ent(a,'raw_response')
    if e is None:return 'missing_evidence'
    if e['presence']=='absent':return 'absent'
    try:b=original(f,a,'raw_response')
    except (KeyError,TypeError,ValueError):return 'unreadable'
    if not b:return 'empty'
    try:t=b.decode('utf-8')
    except UnicodeError:return 'invalid_utf8'
    try:strict(t)
    except ValueError:return 'malformed_json'
    return 'parseable_json'

def event_change(f,a,**kw):
    v=json.loads(original(f,a,'attempt_event'));v.update(kw);put(f,a,'attempt_event',pack(v))

def expected_inventory(f,valid,complete,slots):
    aa=f['envelope']['attempts']; ids={s['record_id'] for s in slots};refs=[a['slot_ref'] for a in aa]
    states=[state(f,a) for a in aa];ev=[]
    for a in aa:
        try:ev.append(strict(original(f,a,'attempt_event').decode()))
        except (ValueError,KeyError,TypeError,UnicodeError):ev.append({})
    return {'planned_slots':len(slots),'present_slots':len(ids & set(refs)),'missing_slots':len(ids-set(refs)),
      'attempts_retained':len(aa),'unplanned_attempts':sum(x not in ids for x in refs),
      'multiple_attempt_slots':sum(refs.count(x)>1 for x in ids),
      'responses_present':sum(ent(a,'raw_response') is not None and ent(a,'raw_response')['presence']=='present' for a in aa),
      'responses_absent':states.count('absent'),'response_evidence_missing':states.count('missing_evidence'),
      'empty_responses':states.count('empty'),'invalid_utf8_responses':states.count('invalid_utf8'),
      'malformed_json_responses':states.count('malformed_json'),'unreadable_responses':states.count('unreadable'),
      'parseable_responses':states.count('parseable_json'),'legacy_records_present':sum(a['legacy_record'] is not None for a in aa),
      'legacy_valid_records':valid,'failed_attempts':sum(e.get('transport_outcome')=='failed' for e in ev),
      'interrupted_attempts':sum(e.get('transport_outcome')=='interrupted' for e in ev),
      'unsupported_attempts':sum(e.get('transport_outcome')=='unsupported' for e in ev),
      'succeeded_attempts':sum(e.get('transport_outcome')=='succeeded' for e in ev),
      'outcome_unavailable_attempts':sum(e.get('transport_outcome') not in ['succeeded','failed','interrupted','unsupported'] for e in ev),
      'selection_unresolved_slots':sum(refs.count(x)>1 for x in ids),'synthetic_complete_comparisons':complete,
      'correctness_denominator':4,'grounding_denominator':4}

def build():
    d=json.loads(DATA.read_text());base=d['fixture'];src=json.loads((ROOT/'benchmark/project-run-binding-0138.json').read_text())['rehearsal']['fixture'];slots=json.loads(src['plan_text'])['slots'];probes=[]
    def add(name,mut=None,accept=True,valid=2,complete=0,rule='E01-E09'):
        f=copy.deepcopy(base)
        if mut:mut(f,f['envelope']['attempts'][1])
        probes.append({'name':name,'fixture':f,'expected_accept':accept,'expected_accounting':expected_inventory(f,valid,complete,slots),'rule':rule})
    add('baseline',complete=1)
    for kind in ['raw_request','raw_response','errors']:
        for label,b in [('empty',b''),('nul',b'X\x00Y'),('invalid-utf8',b'\x00\xff\xfeA'),('truncated-json',b'{"claims":'),('plain-text',b'incomplete transport output'),('json-null',b'null')]:
            def change(f,a,kind=kind,b=b):
                a['legacy_record']=None;put(f,a,kind,b)
                if kind=='raw_response':a['response_parsing']=state(f,a)
                if kind=='raw_request':a['input_binding']='not_bound'
            add('bytes-'+kind+'-'+label,change,valid=1)
    def absent(f,a):
        a['legacy_record']=None;ent(a,'raw_response').update(presence='absent',payload_ref=None);a['response_parsing']='absent'
    add('absent-response',absent,valid=1)
    def empty_attached(f,a):put(f,a,'raw_response',b'');a['response_parsing']='empty'
    add('empty-response-attached-record',empty_attached,accept=False,valid=1)
    add('null-record-intact-response',lambda f,a:a.update(legacy_record=None),valid=1)
    def unbound(f,a):
        b=b'SYNTHETIC independent changed request';put(f,a,'raw_request',b);a['input_binding']='not_bound';r=a['legacy_record']['fields'];r['raw_request']['value']={'text':b.decode(),'sha256':digest(b)};r['effective_prompt_sha256']['value']=digest(b)
    add('unbound-attached-record',unbound)
    for field,value in [('encoding','base64'),('hex','0'),('sha256','0'*64),('byte_size',True),('byte_size',999),('utf8','fabricated view')]:
        def bad(f,a,field=field,value=value):f['payloads'][ent(a,'raw_response')['payload_ref']][field]=value
        add('payload-'+field+'-'+str(value),bad,accept=False,valid=1 if field=='hex' else 2)
    add('dangling-reference',lambda f,a:ent(a,'raw_response').update(payload_ref='synthetic:payload-missing'),accept=False,valid=1)
    add('cross-kind-reference',lambda f,a:ent(a,'raw_response').update(payload_ref=ent(a,'raw_request')['payload_ref']),accept=False,valid=1)
    def orphan(f,a):f['payloads']['synthetic:payload-orphan']={'encoding':'hex','hex':'00','byte_size':0,'sha256':'0'*64,'utf8':'\x00'}
    add('corrupt-unreferenced-payload',orphan,accept=False)
    for key,value in [('attempt_id','synthetic:attempt-other'),('object_id','synthetic://wrong/object'),('producer','trusted:provider'),('producer_version','2'),('created_at','2000-01-01T00:00:00+00:00'),('verification','verified'),('content_type','application/json')]:
        add('metadata-'+key,lambda f,a,key=key,value=value:ent(a,'raw_response').update({key:value}),accept=False)
    add('absent-request',lambda f,a:ent(a,'raw_request').update(presence='absent',payload_ref=None),accept=False,valid=1)
    add('duplicate-attempt-id',lambda f,a:a.update(attempt_id=f['envelope']['attempts'][0]['attempt_id']),accept=False)
    add('duplicate-order',lambda f,a:a.update(attempt_order=1),accept=False)
    add('descending-order',lambda f,a:f['envelope']['attempts'].reverse(),accept=False)
    def gap(f,a):a['attempt_order']=7;event_change(f,a,attempt_order=7)
    add('order-gaps-allowed',gap,complete=1)
    add('boolean-order',lambda f,a:a.update(attempt_order=True),accept=False)
    for key in ['case_id','pair_id','repetition_id','record_id','arm','slot_ref']:
        value='no-tool' if key=='arm' else 'synthetic:unplanned-value'
        add('identity-'+key,lambda f,a,key=key,value=value:a.update({key:value}),accept=False,valid=2 if key=='slot_ref' else 1)
    add('missing-tool-arm',lambda f,a:f['envelope']['attempts'].pop(),valid=1)
    add('missing-both-arms',lambda f,a:f['envelope'].update(attempts=[]),valid=0)
    def duplicate(f,a):
        b=copy.deepcopy(a);b.update(attempt_id='synthetic:attempt-review-3',attempt_order=3)
        for e in b['evidence']:e.update(attempt_id=b['attempt_id'],object_id='synthetic://'+b['attempt_id']+'/'+e['kind'])
        event_change(f,b,attempt_id=b['attempt_id'],attempt_order=3);f['envelope']['attempts'].append(b)
    add('two-successes-one-slot',duplicate,valid=3)
    for outcome in ['failed','interrupted','unsupported']:
        def outcome_mut(f,a,outcome=outcome):a.update(transport_outcome=outcome,legacy_record=None);event_change(f,a,transport_outcome=outcome)
        add('retained-'+outcome,outcome_mut,valid=1)
    def failure_then_success(f,a):
        duplicate(f,a);a.update(transport_outcome='failed',legacy_record=None);event_change(f,a,transport_outcome='failed');put(f,a,'raw_response',b'\x00\xfffailed');a['response_parsing']='invalid_utf8'
    add('failed-binary-then-success',failure_then_success,valid=2)
    add('event-outcome-disagrees',lambda f,a:event_change(f,a,transport_outcome='failed'),accept=False,valid=1)
    add('parsing-label-disagrees',lambda f,a:a.update(response_parsing='empty'),accept=False)
    add('missing-response-evidence',lambda f,a:a['evidence'].remove(ent(a,'raw_response')),accept=False,valid=1)
    for key,value in [('verification','verified'),('real_admission','admitted'),('attempt_selection','last-success'),('provider_verified',True),('restricted_storage','verified'),('isolation','verified')]:
        add('authority-'+key,lambda f,a,key=key,value=value:f['envelope'].update({key:value}),accept=False)
    add('wrong-response-with-old-record',lambda f,a:(put(f,a,'raw_response',b'{"claims":[],"status":"complete","limitations":[]}'),a.update(response_parsing='parseable_json')),accept=False,valid=1)
    for key,value in [('model_identity','synthetic:wrong-provider/model'),('common_prompt_sha256','0'*64)]:
        add('legacy-unjoined-'+key,lambda f,a,key=key,value=value:a['legacy_record']['fields'][key].update(value=value),accept=False,rule='E03/E04; 0138 binding_design settings/inputs/raw_evidence')
    add('legacy-unjoined-original',lambda f,a:a['legacy_record']['fields']['input_evidence']['value'][0].update(sha256='0'*64),accept=False,rule='E03/E04; 0138 linkage input inventory')
    add('legacy-unjoined-tool-response',lambda f,a:a['legacy_record']['fields']['tool_calls']['value'][0].update(response='SYNTHETIC replaced tool output'),accept=False,rule='E03/E04; 0138 raw_evidence tool content joins')
    def failedtool(f,a):a['legacy_record']['fields']['tool_calls']['value'][0]['error']='SYNTHETIC failed tool'
    add('legacy-unjoined-failed-tool',failedtool,accept=False,rule='E03/E04; retained tool_inventory must agree with attached record')
    def null_reason(f,a):a['legacy_record']['fields']['provider_cost']['reason']='changed reason'
    add('legacy-null-reason-drift',null_reason,accept=False,valid=1)
    def pop_null(f,a):a['legacy_record']['fields']['restricted_storage']['value']='verified'
    add('legacy-fabricated-storage',pop_null,accept=False,valid=1)
    return d,src,probes

def main():
    data,base,probes=build()
    spec=[{k:v for k,v in p.items() if k!='fixture'} for p in probes]
    if sys.argv[1]=='prepare':
        (OUT/'attempt-evidence-probe-expectations-0144.json').write_text(json.dumps({'script_sha256':digest(Path(__file__).read_bytes()),'package_sha256':digest(DATA.read_bytes()),'probes':spec},indent=2)+'\n')
        print('Prepared',len(spec),'independent expectations; no checker code executed.');return
    saved=json.loads((OUT/'attempt-evidence-probe-expectations-0144.json').read_text())
    assert saved['script_sha256']==digest(Path(__file__).read_bytes()) and saved['probes']==spec
    for pin in data['pins']:
        raw=(ROOT/pin['path']).read_bytes();assert digest(raw)==pin['sha256'] and len(raw)==pin['byte_size']
    checker=runpy.run_path(str(ROOT/'benchmark/verify_attempt_evidence_0143.py'))
    group=runpy.run_path(str(ROOT/'benchmark/verify_project_run_binding_0138.py'))
    legacy=group['load_legacy_functions']();source={'base':base,'template':json.loads((ROOT/'benchmark/baseline/run-record.template.json').read_text()),'manifest':json.loads(base['manifest_text'])}
    results=[]
    for i,p in enumerate(probes):
        f=p['fixture'];exc=None
        try:decision=checker['validate'](f,source,group,legacy)
